-- Lección 1.1: Escritura de productos con variables
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Escritura de productos con variables', 'Una **variable** es una letra que representa un número. El área de un rectángulo de base $x$ y altura 5 es $x \\times 5$.\n\n**Para escribir un producto con variables:**\n\n1. Se **omite** el signo de multiplicación $\\times$.\n2. Se escribe **primero el número** y después la variable.\n3. Las variables se ordenan **alfabéticamente**.\n\n| Producto | Se escribe |\n|---|---|\n| $x \\times 5$ | $5x$ |\n| $b \\times a$ | $ab$ |\n| $c \\times a$ | $ac$ |\n| $d \\times (-3) \\times c$ | $-3cd$ |', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Productos con variables\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se escribe correctamente $3 \\times b \\times a$?\nopciones:\n- [x] $3ab$\n- [ ] $3ba$\n- [ ] $ab3$\n- [ ] $a3b$\nexplicacion: Primero el número y luego las variables en orden alfabético: $3ab$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se escribe correctamente $x \\times 4 \\times y$?\nopciones:\n- [x] $4xy$\n- [ ] $x4y$\n- [ ] $4yx$\n- [ ] $xy4$\nexplicacion: El número va primero: $4xy$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se escribe correctamente $b \\times (-5) \\times c$?\nopciones:\n- [x] $-5bc$\n- [ ] $b(-5)c$\n- [ ] $5bc$\n- [ ] $-5cb$\nexplicacion: El número con su signo va primero y luego $b$ y $c$ en orden: $-5bc$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cómo se escribe correctamente $-6 \\times y \\times x$?\nopciones:\n- [x] $-6xy$\n- [ ] $-6yx$\n- [ ] $6xy$\n- [ ] $xy - 6$\nexplicacion: Las variables se ordenan alfabéticamente: $-6xy$.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.2: Valor numérico de una expresión
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Valor numérico de una expresión', 'Jimena necesita $3x + 3$ clavos para instalar $x$ láminas en su techo. ¿Cuántos clavos necesita para 6 láminas?\n\nSe **sustituye** $x$ por 6:\n\n$$3x + 3 = 3 \\times 6 + 3 = 18 + 3 = 21$$\n\nNecesita 21 clavos.\n\n**Sustituir** es reemplazar la variable por un número. Al resultado se le llama **valor numérico** de la expresión.\n\n> **Recuerda:** primero se multiplica y después se suma o resta.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Valor numérico\n\n```pregunta\ntipo: numero\nvariables: a = 2..9\nenunciado: Encuentra el valor numérico de $5a - 4$ cuando $a = [[a]]$.\nrespuesta: 5*a - 4\nexplicacion: $5 \\times [[a]] - 4 = [[5*a]] - 4 = [[5*a-4]]$\n```\n\n```pregunta\ntipo: numero\nvariables: x = 1..5\nenunciado: Encuentra el valor numérico de $12 - 4x$ cuando $x = [[x]]$.\nrespuesta: 12 - 4*x\nexplicacion: $12 - 4 \\times [[x]] = 12 - [[4*x]] = [[12-4*x]]$\n```\n\n```pregunta\ntipo: numero\nvariables: x = -5..-1\nenunciado: Encuentra el valor numérico de $2x + 7$ cuando $x = [[x]]$.\nrespuesta: 2*x + 7\nexplicacion: $2 \\times ([[x]]) + 7 = [[2*x]] + 7 = [[2*x+7]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Jimena necesita $3x + 3$ clavos para instalar $x$ láminas. ¿Cuántos clavos necesita para 8 láminas?\nrespuesta: 27\nexplicacion: $3 \\times 8 + 3 = 24 + 3 = 27$ clavos.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.3: Términos y coeficientes
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Términos y coeficientes', 'Cada parte de una expresión que está unida por signos de suma se llama **término**. Al número que multiplica a la variable se le llama **coeficiente**.\n\n**Ejemplo 1:** $3x + 5$ tiene los términos $3x$ y $5$. El coeficiente de $x$ es 3.\n\n**Ejemplo 2:** $a - 5b - 7 = a + (-5b) + (-7)$\n\n- Términos: $a$, $-5b$ y $-7$.\n- El coeficiente de $a$ es 1 y el de $b$ es $-5$.\n\n> **Recuerda:** si la variable no tiene número, su coeficiente es 1 (o $-1$ si tiene signo menos): $-b = -1 \\times b$.', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Términos y coeficientes\n\n```pregunta\ntipo: numero\nenunciado: En la expresión $-7x - 5$, ¿cuál es el coeficiente de $x$?\nrespuesta: -7\nexplicacion: $-7x - 5 = (-7x) + (-5)$. El número que multiplica a $x$ es $-7$.\n```\n\n```pregunta\ntipo: numero\nenunciado: En la expresión $2a - b + 3$, ¿cuál es el coeficiente de $b$?\nrespuesta: -1\nexplicacion: $-b = -1 \\times b$, entonces el coeficiente es $-1$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuáles son los términos de $x - 2y - 10$?\nopciones:\n- [x] $x$, $-2y$ y $-10$\n- [ ] $x$, $2y$ y $10$\n- [ ] $x - 2y$ y $-10$\n- [ ] $x$ y $y$\nexplicacion: $x - 2y - 10 = x + (-2y) + (-10)$, los términos conservan su signo.\n```\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9\nenunciado: En la expresión $-[[a]]y + [[b]]z + 1$, ¿cuál es el coeficiente de $y$?\nrespuesta: -a\nexplicacion: El número que multiplica a $y$ es $-[[a]]$.\n```', FALSE, LAST_INSERT_ID());

-- Lección 1.4: Reducción de términos semejantes
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Reducción de términos semejantes', 'Los **términos semejantes** tienen las mismas variables con los mismos exponentes, como $7x$ y $-4x$. Se pueden **reducir** sumando sus coeficientes. Los números sin variable también se reducen entre sí.\n\n**Ejemplo:**\n\n$$7x + 3 - 4x + 2 = 7x - 4x + 3 + 2 = (7 - 4)x + 5 = 3x + 5$$\n\n**Otro ejemplo:**\n\n$$-10z - 4 - 3 - 5z = (-10 - 5)z - 7 = -15z - 7$$\n\n> **Recuerda:** primero junta los términos con la misma variable, luego los números.', 40, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Reducción de términos semejantes\n\n```pregunta\ntipo: opcion\nenunciado: Reduce $3x - 4 + 2x - 5$\nopciones:\n- [x] $5x - 9$\n- [ ] $5x - 1$\n- [ ] $x - 9$\n- [ ] $-4x$\nexplicacion: $3x + 2x = 5x$ y $-4 - 5 = -9$, entonces $5x - 9$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Reduce $-3 + 2x + 5 - 8x$\nopciones:\n- [x] $-6x + 2$\n- [ ] $10x + 2$\n- [ ] $-6x - 8$\n- [ ] $6x + 2$\nexplicacion: $2x - 8x = -6x$ y $-3 + 5 = 2$, entonces $-6x + 2$.\n```\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = 2..9, c = 1..9\nenunciado: Al reducir $[[a]]x + [[c]] + [[b]]x$, ¿cuál es el coeficiente de $x$?\nrespuesta: a + b\nexplicacion: $[[a]]x + [[b]]x = ([[a]] + [[b]])x = [[a+b]]x$\n```\n\n```pregunta\ntipo: numero\nenunciado: Al reducir $6 + 7x - 4x - 2x - 4$, ¿cuál es el término sin variable?\nrespuesta: 2\nexplicacion: Los números: $6 - 4 = 2$. (La expresión reducida es $x + 2$.)\n```', FALSE, LAST_INSERT_ID());

