-- Lección 2.1: Solución de una ecuación
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Solución de una ecuación', 'Una **ecuación** es una igualdad con una o más variables, por ejemplo $2x + 10 = 20$. Al valor desconocido se le llama **incógnita**, y al valor que cumple la igualdad, **solución**.\n\nPodemos probar valores de $x$:\n\n| $x$ | $2x + 10$ | ¿Es igual a 20? |\n|---|---|---|\n| 3 | 16 | No |\n| 4 | 18 | No |\n| 5 | 20 | **Sí** |\n\nLa solución es $x = 5$.\n\n> **Para comprobar** una solución, sustitúyela en la ecuación y revisa que ambos lados den lo mismo.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Solución de ecuaciones\n\n```pregunta\ntipo: numero\nenunciado: ¿Cuál es la solución de $2x + 10 = 20$?\nrespuesta: 5\nexplicacion: $2 \\times 5 + 10 = 20$ ✓\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál de estas ecuaciones tiene como solución $x = 2$?\nopciones:\n- [x] $3x + 1 = 7$\n- [ ] $2x + 5 = 11$\n- [ ] $-4x + 2 = -8$\nexplicacion: $3 \\times 2 + 1 = 7$ ✓. En las otras: $2 \\times 2 + 5 = 9$ y $-4 \\times 2 + 2 = -6$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál de estas ecuaciones tiene como solución $x = -3$?\nopciones:\n- [x] $-6x - 2 = 16$\n- [ ] $4x + 6 = 18$\n- [ ] $5x - 2 = 17$\nexplicacion: $-6 \\times (-3) - 2 = 18 - 2 = 16$ ✓\n```\n\n```pregunta\ntipo: opcion\nenunciado: En una ecuación, ¿cómo se llama el valor desconocido representado por una variable?\nopciones:\n- [x] Incógnita\n- [ ] Coeficiente\n- [ ] Término\nexplicacion: Al valor desconocido se le llama incógnita.\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.2: Ecuaciones de la forma x − a = b
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Ecuaciones de la forma x − a = b', '**Resolver** una ecuación es encontrar el valor de $x$. Para despejar $x$ en $x - a = b$, se **suma $a$ en ambos lados**:\n\n$$x - 5 = 10$$\n$$x - 5 + 5 = 10 + 5$$\n$$x = 15$$\n\n**Comprobación:** $15 - 5 = 10$ ✓\n\n**Otro ejemplo:**\n\n$$-2 + x = 2 \\;\\Rightarrow\\; -2 + 2 + x = 2 + 2 \\;\\Rightarrow\\; x = 4$$\n\n> **Recuerda:** lo que hagas en un lado de la ecuación, hazlo también en el otro.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Ecuaciones x − a = b\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = -5..9\nenunciado: Resuelve $x - [[a]] = [[b]]$\nrespuesta: b + a\nexplicacion: Se suma [[a]] en ambos lados: $x = [[b]] + [[a]] = [[b+a]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $-3 + x = 2$\nrespuesta: 5\nexplicacion: $x = 2 + 3 = 5$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $x - 11 = 4$\nrespuesta: 15\nexplicacion: $x = 4 + 11 = 15$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $-4 + x = -9$\nrespuesta: -5\nexplicacion: $x = -9 + 4 = -5$\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.3: Ecuaciones de la forma x + a = b
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Ecuaciones de la forma x + a = b', 'Para despejar $x$ en $x + a = b$, se **resta $a$ en ambos lados**:\n\n$$x + 7 = 4$$\n$$x + 7 - 7 = 4 - 7$$\n$$x = -3$$\n\n**Comprobación:** $-3 + 7 = 4$ ✓\n\n**Otro ejemplo:**\n\n$$3 + x = -2 \\;\\Rightarrow\\; 3 - 3 + x = -2 - 3 \\;\\Rightarrow\\; x = -5$$', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Ecuaciones x + a = b\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, b = -5..9\nenunciado: Resuelve $x + [[a]] = [[b]]$\nrespuesta: b - a\nexplicacion: Se resta [[a]] en ambos lados: $x = [[b]] - [[a]] = [[b-a]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $4 + x = -3$\nrespuesta: -7\nexplicacion: $x = -3 - 4 = -7$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $x + 6 = 6$\nrespuesta: 0\nexplicacion: $x = 6 - 6 = 0$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $7 + x = -5$\nrespuesta: -12\nexplicacion: $x = -5 - 7 = -12$\n```', FALSE, LAST_INSERT_ID());

-- Lección 2.4: Ecuaciones de la forma ax = b
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Ecuaciones de la forma ax = b', 'Para despejar $x$ en $ax = b$, se **dividen ambos lados entre $a$** (el coeficiente de $x$):\n\n$$9x = -45$$\n$$\\frac{9x}{9} = \\frac{-45}{9}$$\n$$x = -5$$\n\n**Otro ejemplo:**\n\n$$-10x = 20 \\;\\Rightarrow\\; x = \\frac{20}{-10} = -2$$\n\n> **Recuerda:** al dividir, aplica la regla de los signos.', 40, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Ecuaciones ax = b\n\n```pregunta\ntipo: numero\nvariables: a = 2..9, k = -6..6\nenunciado: Resuelve $[[a]]x = [[a*k]]$\nrespuesta: k\nexplicacion: Se dividen ambos lados entre [[a]]: $x = \\frac{[[a*k]]}{[[a]]} = [[k]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $-5x = 25$\nrespuesta: -5\nexplicacion: $x = \\frac{25}{-5} = -5$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $8x = -56$\nrespuesta: -7\nexplicacion: $x = \\frac{-56}{8} = -7$\n```\n\n```pregunta\ntipo: numero\nenunciado: Resuelve $-7x = -21$\nrespuesta: 3\nexplicacion: $x = \\frac{-21}{-7} = 3$\n```', FALSE, LAST_INSERT_ID());

-- Tema 3: Razones y proporciones
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Razones y proporciones', 30, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 3.1: Razones
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Razones', 'Rosa usa 2 cucharadas de azúcar y 3 de leche en polvo para su café. La relación entre azúcar y leche se escribe:\n\n$$2 : 3 \\quad \\text{y se lee "dos es a tres"}$$\n\nUna **razón** compara dos cantidades **con la misma unidad de medida**. Se escribe $a : b$.\n\n- Al primer término $a$ se le llama **antecedente**.\n- Al segundo término $b$ se le llama **consecuente**.\n\n**Ejemplo:** la razón de 9 m a 300 cm. Primero se usa la misma unidad: $9 \\text{ m} = 900 \\text{ cm}$. La razón es $900 : 300$.\n\nEl **valor de razón** es el resultado de dividir $a \\div b$: el valor de $2 : 3$ es $\\frac{2}{3}$.', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Razones\n\n```pregunta\ntipo: opcion\nenunciado: Rosa usa 2 cucharadas de azúcar y 3 de leche. ¿Cuál es la razón de azúcar a leche?\nopciones:\n- [x] $2 : 3$\n- [ ] $3 : 2$\n- [ ] $2 : 5$\n- [ ] $5 : 3$\nexplicacion: El azúcar va primero (antecedente) y la leche después (consecuente): $2 : 3$.\n```\n\n```pregunta\ntipo: opcion\nenunciado: En la razón $9 : 3$, ¿cuál es el antecedente?\nopciones:\n- [x] 9\n- [ ] 3\n- [ ] 12\nmezclar: no\nexplicacion: El antecedente es el primer término de la razón.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál es la razón de 12 km a 36,000 m?\nopciones:\n- [x] $12{,}000 : 36{,}000$\n- [ ] $12 : 36{,}000$\n- [ ] $36{,}000 : 12$\n- [ ] $12{,}000 : 36$\nexplicacion: Se usa la misma unidad: $12 \\text{ km} = 12{,}000 \\text{ m}$. La razón es $12{,}000 : 36{,}000$ (que también es $12 : 36$ en km).\n```\n\n```pregunta\ntipo: fraccion\nenunciado: En un grupo hay 10 hombres y 15 mujeres. ¿Cuál es el valor de la razón de hombres a mujeres? (escríbelo como fracción, ej. 2/5)\nnumerador: 10\ndenominador: 15\nforma: equivalente\nexplicacion: $10 \\div 15 = \\frac{10}{15} = \\frac{2}{3}$\n```', FALSE, LAST_INSERT_ID());

-- Lección 3.2: Razones equivalentes
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Razones equivalentes', 'Ana mezcla 2 dL de concentrado de horchata con 24 dL de agua en un pichel, y 3 dL con 36 dL en otro.\n\n$$\\text{Pichel A: } \\frac{2}{24} = \\frac{1}{12} \\qquad \\text{Pichel B: } \\frac{3}{36} = \\frac{1}{12}$$\n\nLos valores de razón son iguales, entonces las razones son **equivalentes**: $2 : 24 = 3 : 36$.\n\n- Dos razones con el mismo valor de razón son **razones equivalentes**.\n- A la igualdad entre dos razones equivalentes se le llama **proporción**.\n\n> **Para saber si son equivalentes**, simplifica los valores de razón y compáralos.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Razones equivalentes\n\n```pregunta\ntipo: opcion\nenunciado: ¿Son equivalentes las razones $6 : 8$ y $9 : 12$?\nopciones:\n- [x] Sí\n- [ ] No\nmezclar: no\nexplicacion: $\\frac{6}{8} = \\frac{3}{4}$ y $\\frac{9}{12} = \\frac{3}{4}$. Tienen el mismo valor.\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Son equivalentes las razones $8 : 12$ y $20 : 24$?\nopciones:\n- [ ] Sí\n- [x] No\nmezclar: no\nexplicacion: $\\frac{8}{12} = \\frac{2}{3}$ pero $\\frac{20}{24} = \\frac{5}{6}$. Son diferentes.\n```\n\n```pregunta\ntipo: fraccion\nvariables: a = 1..5, k = 2..9\nenunciado: ¿Cuál es el valor de la razón $[[a]] : [[a*k + 1]]$? (escríbelo como fracción)\nnumerador: a\ndenominador: a*k + 1\nforma: equivalente\nexplicacion: El valor de razón es $[[a]] \\div [[a*k+1]] = \\frac{[[a]]}{[[a*k+1]]}$\n```\n\n```pregunta\ntipo: opcion\nenunciado: El edificio A mide 8 m y proyecta una sombra de 6 m; el edificio B mide 12 m y su sombra es de 9 m. ¿La razón de las alturas ($8 : 12$) es equivalente a la de las sombras ($6 : 9$)?\nopciones:\n- [x] Sí\n- [ ] No\nmezclar: no\nexplicacion: $\\frac{8}{12} = \\frac{2}{3}$ y $\\frac{6}{9} = \\frac{2}{3}$. Son equivalentes.\n```', FALSE, LAST_INSERT_ID());

-- Lección 3.3: Proporciones
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Proporciones', 'Si $x : 3 = 10 : 15$, ¿cuánto vale $x$?\n\nEn la proporción $a : b = c : d$, a $a$ y $d$ se les llama **términos extremos**, y a $b$ y $c$, **términos medios**. Se cumple que:\n\n$$\\text{(producto de extremos)} = \\text{(producto de medios)} \\qquad ad = bc$$\n\n**Ejemplo:** $x : 3 = 10 : 15$\n\n$$15x = 3 \\times 10$$\n$$15x = 30$$\n$$x = 2$$\n\n**Comprobación:** $2 : 3$ y $10 : 15$ valen $\\frac{2}{3}$ ✓', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Proporciones\n\n```pregunta\ntipo: numero\nvariables: v = 1..9, b = 2..6, k = 2..5\nenunciado: Encuentra el valor de $x$: $x : [[b]] = [[v*k]] : [[b*k]]$\nrespuesta: v\nexplicacion: $[[b*k]]x = [[b]] \\times [[v*k]] = [[b*v*k]]$, entonces $x = [[b*v*k]] \\div [[b*k]] = [[v]]$\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra el valor de $x$: $3 : x = 2 : 6$\nrespuesta: 9\nexplicacion: $3 \\times 6 = 2x$, entonces $18 = 2x$ y $x = 9$.\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra el valor de $x$: $9 : 6 = 12 : x$\nrespuesta: 8\nexplicacion: $9x = 6 \\times 12 = 72$, entonces $x = 8$.\n```\n\n```pregunta\ntipo: numero\nenunciado: Encuentra el valor de $x$: $15 : 12 = 10 : x$\nrespuesta: 8\nexplicacion: $15x = 12 \\times 10 = 120$, entonces $x = 8$.\n```', FALSE, LAST_INSERT_ID());

-- Tema 4: Porcentajes
INSERT INTO Temas (Tema_Nombre, Tema_Orden, Plan_Id) VALUES ('Porcentajes', 40, @plan_id);
SET @tema_id = LAST_INSERT_ID();

-- Lección 4.1: Porcentajes y números decimales
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Porcentajes y números decimales', 'Un instituto tiene 200 estudiantes y 80 son de primer grado. ¿Qué porcentaje representan?\n\n$$\\frac{80}{200} = 0.40 \\qquad 0.40 \\times 100 = 40\\%$$\n\n- **De decimal a porcentaje:** se multiplica por 100 y se escribe %. $0.35 \\to 35\\%$\n- **De porcentaje a decimal:** se divide entre 100. $25\\% \\to 0.25$\n\n| Decimal | 0.15 | 0.25 | 0.5 | 0.75 | 1 |\n|---|---|---|---|---|---|\n| Porcentaje | 15% | 25% | 50% | 75% | 100% |', 10, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Porcentajes\n\n```pregunta\ntipo: numero\nenunciado: Convierte $0.56$ a porcentaje (escribe solo el número, sin %).\nrespuesta: 56\nexplicacion: $0.56 \\times 100 = 56\\%$\n```\n\n```pregunta\ntipo: numero\nenunciado: Convierte $0.07$ a porcentaje (escribe solo el número, sin %).\nrespuesta: 7\nexplicacion: $0.07 \\times 100 = 7\\%$\n```\n\n```pregunta\ntipo: numero\nvariables: n = 1..99\nenunciado: Escribe $[[n]]\\%$ como número decimal.\nrespuesta: n / 100\nexplicacion: Se divide entre 100: $[[n]] \\div 100$.\n```\n\n```pregunta\ntipo: numero\nenunciado: En un instituto de 200 estudiantes, 70 son de segundo grado. ¿Qué porcentaje representan? (escribe solo el número)\nrespuesta: 35\nexplicacion: $\\frac{70}{200} = 0.35$, y $0.35 \\times 100 = 35\\%$\n```', FALSE, LAST_INSERT_ID());

-- Lección 4.2: Porcentaje de una cantidad
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Porcentaje de una cantidad', 'A un concierto en Cuyotenango podían ir 200 personas, pero solo el 80% compró boleto. ¿Cuántas personas compraron boleto?\n\nSe **multiplica el porcentaje por la cantidad total**. El porcentaje se puede escribir como decimal o como fracción con denominador 100:\n\n$$80\\% \\times 200 = 0.8 \\times 200 = 160$$\n$$80\\% \\times 200 = \\frac{80}{100} \\times 200 = 160$$\n\nCompraron boleto 160 personas.', 20, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Porcentaje de una cantidad\n\n```pregunta\ntipo: numero\nenunciado: Un equipo de fútbol jugó 10 partidos y ganó el 70%. ¿Cuántos partidos ganó?\nrespuesta: 7\nexplicacion: $0.7 \\times 10 = 7$ partidos.\n```\n\n```pregunta\ntipo: numero\nenunciado: Un agricultor tiene $3{,}000$ m² y siembra el 60%. ¿Cuántos m² siembra?\nrespuesta: 1800\nexplicacion: $0.6 \\times 3{,}000 = 1{,}800$ m².\n```\n\n```pregunta\ntipo: numero\nenunciado: Un instituto tiene 400 alumnos y el 40% son mujeres. ¿Cuántas mujeres hay?\nrespuesta: 160\nexplicacion: $0.4 \\times 400 = 160$ mujeres.\n```\n\n```pregunta\ntipo: numero\nvariables: p = 10|20|25|30|40|50, t = 100|200|300|400|500\nenunciado: ¿Cuánto es el $[[p]]\\%$ de [[t]]?\nrespuesta: p * t / 100\nexplicacion: $\\frac{[[p]]}{100} \\times [[t]] = [[p*t/100]]$\n```', FALSE, LAST_INSERT_ID());

-- Lección 4.3: Descuentos
INSERT INTO Lecciones (Leccion_Nombre, Leccion_Contenido, Leccion_Orden, Tema_Id) VALUES ('Descuentos', 'Unas zapatillas cuestan Q200.00 y tienen un **descuento** del 30%.\n\n**1. Se calcula el descuento:**\n\n$$\\text{Descuento} = 30\\% \\times 200 = \\frac{30}{100} \\times 200 = 60$$\n\n**2. Se resta al precio original:**\n\n$$\\text{Precio a pagar} = 200 - 60 = 140$$\n\nSe pagan Q140.00.\n\n> **Fórmulas:**\n> Descuento = porcentaje de descuento × precio original\n> Precio de venta = precio original − descuento', 30, @tema_id);
INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id) VALUES ('# Descuentos\n\n```pregunta\ntipo: numero\nenunciado: A un artículo de Q500.00 se le descuenta el 10%. ¿De cuántos quetzales es el descuento?\nrespuesta: 50\nexplicacion: $\\frac{10}{100} \\times 500 = 50$ quetzales.\n```\n\n```pregunta\ntipo: numero\nenunciado: Una camisa costaba Q350.00 y le hicieron un descuento del 20%. ¿De cuánto fue el descuento?\nrespuesta: 70\nexplicacion: $\\frac{20}{100} \\times 350 = 70$ quetzales.\n```\n\n```pregunta\ntipo: numero\nenunciado: Con el descuento del 20% sobre Q350.00, ¿cuánto se paga por la camisa?\nrespuesta: 280\nexplicacion: $350 - 70 = 280$ quetzales.\n```\n\n```pregunta\ntipo: numero\nvariables: precio = 100|200|300|400|500, d = 10|20|30|40\nenunciado: Un artículo cuesta Q[[precio]].00 y tiene $[[d]]\\%$ de descuento. ¿Cuánto se paga? (en quetzales)\nrespuesta: precio - precio * d / 100\nexplicacion: Descuento: $\\frac{[[d]]}{100} \\times [[precio]] = [[precio*d/100]]$. Se paga $[[precio]] - [[precio*d/100]] = [[precio - precio*d/100]]$ quetzales.\n```', FALSE, LAST_INSERT_ID());

COMMIT;

SELECT p.Plan_Id, p.Plan_Nombre, COUNT(DISTINCT t.Tema_Id) AS Temas, COUNT(DISTINCT l.Leccion_Id) AS Lecciones, COUNT(e.Ejercicio_Id) AS Ejercicios
FROM Planes_Estudio p JOIN Temas t ON t.Plan_Id = p.Plan_Id JOIN Lecciones l ON l.Tema_Id = t.Tema_Id
LEFT JOIN Ejercicios e ON e.Leccion_Id = l.Leccion_Id WHERE p.Plan_Id = @plan_id GROUP BY p.Plan_Id, p.Plan_Nombre;
